// ================================================================
// LONELY STONER SYSTEM — HUD UI Script
// Version: 1.0
// Handles: All touch input, dialog menus, and display updates.
//          This is what the player directly interacts with.
//
// HUD PRIM STRUCTURE (link numbers — adjust to match your build):
//   Root prim     : HUD background, touch opens main menu
//   Link 2        : "btn_smoke"    — smoke button
//   Link 3        : "btn_inventory"— inventory button
//   Link 4        : "btn_grow"     — grow status button
//   Link 5        : "btn_session"  — session button
//   Link 6        : "btn_pass"     — pass button
//   Link 7        : "btn_stats"    — stats button
//   Link 8        : "btn_store"    — opens store (URL)
//
// BUTTON GLOW STATES:
//   Active/highlighted buttons glow at 0.1
//   Inactive buttons glow at 0.0
// ================================================================

integer CHAN_UI        = 100;
integer CHAN_COMMS     = 200;
integer CHAN_INVENTORY = 300;
integer CHAN_IDENTITY  = 400;
integer CHAN_ANIMATION = 500;

// Dialog listen channels — use negative numbers to avoid chat noise
integer DIALOG_CHAN_MAIN    = -11111;
integer DIALOG_CHAN_SMOKE   = -11112;
integer DIALOG_CHAN_INV     = -11113;
integer DIALOG_CHAN_PASS    = -11114;
integer DIALOG_CHAN_SESSION = -11115;
integer DIALOG_CHAN_QUALITY = -11116;

integer g_listenMain;
integer g_listenSmoke;
integer g_listenInv;
integer g_listenPass;
integer g_listenSession;
integer g_listenQuality;

key     g_ownerKey;
string  g_ownerName;

// Cached identity data (updated via link messages)
string  g_playerName;
integer g_totalSmoked;
string  g_favoriteStrain;
integer g_repScore;

// Cached inventory display string (updated via link messages)
string  g_inventoryDisplay = "Loading...";

// Cached animation state
string  g_animState = "IDLE";

// Pending pass target
key     g_passTarget = NULL_KEY;
string  g_passItemType;
string  g_passStrain;
string  g_passQuality;

// ----------------------------------------------------------------
// Utility: close all open dialog listens to keep things clean
// ----------------------------------------------------------------
closeAllListens()
{
    if (g_listenMain)    { llListenRemove(g_listenMain);    g_listenMain    = 0; }
    if (g_listenSmoke)   { llListenRemove(g_listenSmoke);   g_listenSmoke   = 0; }
    if (g_listenInv)     { llListenRemove(g_listenInv);     g_listenInv     = 0; }
    if (g_listenPass)    { llListenRemove(g_listenPass);    g_listenPass    = 0; }
    if (g_listenSession) { llListenRemove(g_listenSession); g_listenSession = 0; }
    if (g_listenQuality) { llListenRemove(g_listenQuality); g_listenQuality = 0; }
}

// ----------------------------------------------------------------
// Set a prim's glow to indicate active/inactive state
// ----------------------------------------------------------------
setButtonGlow(integer linkNum, float glowVal)
{
    llSetLinkPrimitiveParamsFast(linkNum, [PRIM_GLOW, ALL_SIDES, glowVal]);
}

// ----------------------------------------------------------------
// MAIN MENU — shown when root prim is touched or no button matched
// ----------------------------------------------------------------
showMainMenu()
{
    closeAllListens();
    string status = "Smoking: " + g_animState;
    if (g_animState != "IDLE")
    {
        list parts = llParseString2List(g_animState, ["|"], []);
        status = "Smoking: " + llList2String(parts,1) + " [" + llList2String(parts,2) + "]";
    }

    g_listenMain = llListen(DIALOG_CHAN_MAIN, "", g_ownerKey, "");
    llDialog(g_ownerKey,
        "=== LONELY STONER ===\n" + status + "\nRep: " + (string)g_repScore,
        ["Smoke", "Inventory", "Grow", "Session", "Pass", "Stats", "Store", "Close"],
        DIALOG_CHAN_MAIN);
    llSetTimerEvent(30.0); // auto-close timeout
}

// ----------------------------------------------------------------
// SMOKE MENU — choose what to smoke from inventory
// ----------------------------------------------------------------
showSmokeMenu()
{
    closeAllListens();
    g_listenSmoke = llListen(DIALOG_CHAN_SMOKE, "", g_ownerKey, "");
    llDialog(g_ownerKey,
        "=== SMOKE ===\nWhat do you want to smoke?\n\n" + g_inventoryDisplay,
        ["Joint", "Blunt", "Pipe", "Bong", "Edible", "Dab", "Back"],
        DIALOG_CHAN_SMOKE);
}

// ----------------------------------------------------------------
// QUALITY SELECTION — after choosing item type, pick quality tier
// ----------------------------------------------------------------
showQualityMenu(string itemType)
{
    closeAllListens();
    g_listenQuality = llListen(DIALOG_CHAN_QUALITY, "", g_ownerKey, "");
    llDialog(g_ownerKey,
        "=== SELECT QUALITY ===\nChoose your " + itemType + ":",
        ["Reggie", "Mids", "Loud", "Exotic", "Back"],
        DIALOG_CHAN_QUALITY);
}

// ----------------------------------------------------------------
// INVENTORY MENU — view and manage carried items
// ----------------------------------------------------------------
showInventoryMenu()
{
    closeAllListens();
    llMessageLinked(LINK_SET, CHAN_INVENTORY, "REQUEST_INVENTORY", NULL_KEY);
    g_listenInv = llListen(DIALOG_CHAN_INV, "", g_ownerKey, "");
    llDialog(g_ownerKey,
        "=== INVENTORY ===\n" + g_inventoryDisplay,
        ["Load Jar", "Fill Bag", "Use Item", "Back"],
        DIALOG_CHAN_INV);
}

// ----------------------------------------------------------------
// SESSION MENU — start or manage a smoke session
// ----------------------------------------------------------------
showSessionMenu()
{
    closeAllListens();
    g_listenSession = llListen(DIALOG_CHAN_SESSION, "", g_ownerKey, "");
    llDialog(g_ownerKey,
        "=== SESSION ===\nSpark a session and invite nearby friends.\nEveryone shares the same circle.",
        ["Spark Session", "End Session", "Back"],
        DIALOG_CHAN_SESSION);
}

// ----------------------------------------------------------------
// PASS MENU — choose a nearby player to pass to
// ----------------------------------------------------------------
showPassMenu()
{
    closeAllListens();
    // Get a list of nearby avatars in 10m radius
    list agents = llGetAgentList(AGENT_LIST_PARCEL, []);
    list buttons;
    integer i;
    for (i = 0; i < llGetListLength(agents) && i < 9; i++)
    {
        key   agent = llList2Key(agents, i);
        if (agent == g_ownerKey) jump skip_self;
        string aName = llKey2Name(agent);
        buttons += [llGetSubString(aName, 0, 11)]; // truncate for button
        @skip_self;
    }
    if (llGetListLength(buttons) == 0)
    {
        llOwnerSay("No one nearby to pass to.");
        return;
    }
    buttons += ["Back"];
    g_listenPass = llListen(DIALOG_CHAN_PASS, "", g_ownerKey, "");
    llDialog(g_ownerKey,
        "=== PASS ===\nChoose who to pass to:",
        buttons, DIALOG_CHAN_PASS);
}

// ----------------------------------------------------------------
// STATS DISPLAY
// ----------------------------------------------------------------
showStats()
{
    llMessageLinked(LINK_SET, CHAN_IDENTITY, "REQUEST_STATS_CARD", NULL_KEY);
    // Response comes back via link_message SHOW_STATS and we ownerSay it
}

// ----------------------------------------------------------------
// Start a session — rez the session object at player's feet
// ----------------------------------------------------------------
startSession()
{
    // The session object must be in HUD inventory
    if (llGetInventoryType("LSS_SessionObject") != INVENTORY_OBJECT)
    {
        llOwnerSay("[Error] Session object not found in HUD. Please contact support.");
        return;
    }

    vector rezPos = llGetPos(); // HUD is worn, pos = avatar pos
    // Rez slightly in front of avatar
    rotation rot   = llGetRot();
    vector   front = llRot2Fwd(rot);
    vector   pos   = rezPos + (front * 1.0) + <0,0,0.1>;

    llRezObject("LSS_SessionObject", pos, ZERO_VECTOR, ZERO_ROTATION, 0);
    // The session object will send back its key via comms once it rezzes
    // Handled in HUD_Comms via the on_rez callback from the session object
    llOwnerSay("Sparking a session... invite sent to nearby players.");
}

// ================================================================
default
{
    state_entry()
    {
        g_ownerKey  = llGetOwner();
        g_ownerName = llKey2Name(g_ownerKey);
        // Request fresh data from sibling scripts
        llMessageLinked(LINK_SET, CHAN_IDENTITY, "REQUEST_IDENTITY", NULL_KEY);
        llMessageLinked(LINK_SET, CHAN_INVENTORY, "REQUEST_INVENTORY", NULL_KEY);
    }

    on_rez(integer start_param)
    {
        llResetScript();
    }

    changed(integer change)
    {
        if (change & CHANGED_OWNER) llResetScript();
    }

    timer()
    {
        // Dialog timeout — close listens to avoid memory leak
        closeAllListens();
        llSetTimerEvent(0.0);
    }

    // ----------------------------------------------------------
    // Touch handling — each prim routes to the right menu
    // ----------------------------------------------------------
    touch_start(integer nd)
    {
        key toucher = llDetectedKey(0);
        if (toucher != g_ownerKey) return; // owner only

        integer linkNum  = llDetectedLinkNumber(0);
        string  primName = llGetLinkName(linkNum);

        if (primName == "btn_smoke"     || primName == "ROOT") showSmokeMenu();
        else if (primName == "btn_inventory")  showInventoryMenu();
        else if (primName == "btn_grow")
        {
            // Just say grow status — grow objects report to HUD
            llOwnerSay("Check your grow area. Touch a plant for status.");
        }
        else if (primName == "btn_session")    showSessionMenu();
        else if (primName == "btn_pass")       showPassMenu();
        else if (primName == "btn_stats")      showStats();
        else if (primName == "btn_store")
        {
            llLoadURL(g_ownerKey, "Visit the Lonely Stoner Store!",
                      "https://marketplace.secondlife.com"); // replace with your store URL
        }
        else showMainMenu(); // anything else opens main
    }

    // ----------------------------------------------------------
    // Dialog responses
    // ----------------------------------------------------------
    listen(integer channel, string name, key id, string msg)
    {
        if (id != g_ownerKey) return;
        closeAllListens();
        llSetTimerEvent(0.0);

        // MAIN MENU
        if (channel == DIALOG_CHAN_MAIN)
        {
            if (msg == "Smoke")       showSmokeMenu();
            else if (msg == "Inventory") showInventoryMenu();
            else if (msg == "Grow")   llOwnerSay("Touch a plant on your land to check its status.");
            else if (msg == "Session") showSessionMenu();
            else if (msg == "Pass")   showPassMenu();
            else if (msg == "Stats")  showStats();
            else if (msg == "Store")
                llLoadURL(g_ownerKey, "Lonely Stoner Store", "https://marketplace.secondlife.com");
            // "Close" does nothing — menu just closes
        }

        // SMOKE MENU — pick item type
        else if (channel == DIALOG_CHAN_SMOKE)
        {
            if (msg == "Back") { showMainMenu(); return; }
            // Store item type choice, then ask quality
            g_passItemType = llToLower(msg); // reuse passItemType as temp storage
            showQualityMenu(msg);
        }

        // QUALITY SELECTION
        else if (channel == DIALOG_CHAN_QUALITY)
        {
            if (msg == "Back") { showSmokeMenu(); return; }
            string quality = llToLower(msg); // reggie, mids, loud, exotic

            // Check inventory for this item+quality, then tell comms to consume it
            // Format: REMOVE_ITEM|itemType|strainName|quality|qty|packager
            // For smoking we don't filter by strain — use first available match
            // The inventory manager will pick the first matching slot
            llMessageLinked(LINK_SET, CHAN_INVENTORY,
                "REMOVE_ITEM|" + g_passItemType + "||" + quality + "|1|", NULL_KEY);
            // Animation triggered by REMOVE_SUCCESS → comms → animation
        }

        // INVENTORY MENU
        else if (channel == DIALOG_CHAN_INV)
        {
            if (msg == "Back") { showMainMenu(); return; }
            if (msg == "Load Jar")
                llOwnerSay("Touch your weed jar to load it from inventory.");
            else if (msg == "Fill Bag")
                llOwnerSay("Touch your bagging table to package your flower.");
            else if (msg == "Use Item")
                llOwnerSay("Use the Smoke menu to consume items.");
        }

        // SESSION MENU
        else if (channel == DIALOG_CHAN_SESSION)
        {
            if (msg == "Back") { showMainMenu(); return; }
            if (msg == "Spark Session") startSession();
            else if (msg == "End Session")
                llMessageLinked(LINK_SET, CHAN_COMMS, "LEAVE_SESSION", NULL_KEY);
        }

        // PASS MENU — player name selected
        else if (channel == DIALOG_CHAN_PASS)
        {
            if (msg == "Back") { showMainMenu(); return; }
            // Find the full key from nearby agents matching the truncated name
            list agents = llGetAgentList(AGENT_LIST_PARCEL, []);
            integer i;
            for (i = 0; i < llGetListLength(agents); i++)
            {
                key    agent = llList2Key(agents, i);
                string aName = llGetSubString(llKey2Name(agent), 0, 11);
                if (aName == msg)
                {
                    g_passTarget = agent;
                    jump found_target;
                }
            }
            llOwnerSay("Couldn't find that player. They may have moved away.");
            return;
            @found_target;

            // Now ask what to pass — open smoke-style menu to pick item
            llOwnerSay("Choose what to pass to " + llKey2Name(g_passTarget) + ".");
            showSmokeMenu(); // Reuse smoke menu, pass logic differs in final flow
            // TODO: differentiate pass flow from smoke flow with a state flag
        }
    }

    // ----------------------------------------------------------
    // Incoming data from sibling scripts to update UI state
    // ----------------------------------------------------------
    link_message(integer sender_num, integer num, string msg, key id)
    {
        if (num != CHAN_UI) return;

        list   parts = llParseString2List(msg, ["|"], []);
        string cmd   = llList2String(parts, 0);

        // Identity script sends stats card text
        if (cmd == "SHOW_STATS")
        {
            llOwnerSay(llList2String(parts, 1));
        }

        // Inventory script sends updated display string
        else if (cmd == "UPDATE_INVENTORY_DISPLAY")
        {
            g_inventoryDisplay = llList2String(parts, 1);
        }

        // Animation state changed
        else if (cmd == "ANIM_STATE")
        {
            g_animState = llList2String(parts, 1);
            // Could update a HUD display prim here with texture swap
        }

        // Session invite from another player arrived
        else if (cmd == "SHOW_SESSION_INVITE")
        {
            // SHOW_SESSION_INVITE|hostName|sessionObjectKey|strain|quality
            string hostName = llList2String(parts, 1);
            key    sessKey  = (key)llList2String(parts, 2);
            string strain   = llList2String(parts, 3);
            string quality  = llList2String(parts, 4);

            integer invChan = -22222;
            integer inv = llListen(invChan, "", g_ownerKey, "");
            llDialog(g_ownerKey,
                hostName + " is sparking a session!\n" +
                "Strain: " + quality + " " + strain + "\nJoin?",
                ["Join!", "No Thanks"],
                invChan);
            // Response handled inline via a separate listen
            // In a full implementation this would be its own state or handler
        }

        // Session ended
        else if (cmd == "SESSION_ENDED")
        {
            g_animState = "IDLE";
            llOwnerSay("Session ended.");
        }

        // Item used successfully
        else if (cmd == "ITEM_USED")
        {
            // Feedback is handled by individual systems
        }

        // Item use failed (not enough)
        else if (cmd == "ITEM_FAILED")
        {
            llOwnerSay("You don't have enough of that.");
        }

        // Identity data received — cache relevant fields
        else if (cmd == "IDENTITY_DATA")
        {
            list iparts = llParseString2List(llList2String(parts, 1), ["|"], []);
            g_playerName     = llList2String(iparts, 0);
            g_totalSmoked    = (integer)llList2String(iparts, 2);
            g_favoriteStrain = llList2String(iparts, 6);
            g_repScore       = (integer)llList2String(iparts, 7);
        }
    }
}

