        else if (cmd == "SHOW_SESSION_INVITE")
        {
            // SHOW_SESSION_INVITE|hostName|sessionObjectKey|strain|quality
            string hostName = llList2String(parts, 1);
            key    sessKey  = (key)llList2String(parts, 2);
            string strain   = llList2String(parts, 3);
            string quality  = llList2String(parts, 4);

            integer invChan = -22222;
            integer inv = llListen(invChan, "", g_ownerKey, "");
            llDialog(g_ownerKey,
