     1	// ================================================================
     2	// LONELY STONER SYSTEM — HUD Comms Script
     3	// Version: 1.0
     4	// Handles: ALL external communication between the HUD and world
     5	//          objects (plants, jars, crafting tables, session objects,
     6	//          other player HUDs). The switchboard.
     7	//
     8	// Channel Strategy:
     9	//   g_privateChannel — derived from owner UUID, used for all
    10	//                      direct HUD<->object communication. Private
    11	//                      per player so objects can target the right HUD.
    12	//   PUBLIC_SESSION_CHAN — used to broadcast/receive session invites
    13	//                         in the region. Known channel, but messages
    14	//                         carry UUID for verification.
    15	// ================================================================
    16	
    17	integer CHAN_UI        = 100;
    18	integer CHAN_COMMS     = 200;
    19	integer CHAN_INVENTORY = 300;
