// ----------------------------------------------------------------
integer derivePrivateChannel(key ownerID)
{
    string hexSub = llGetSubString((string)ownerID, 0, 6);
    // Strip hyphens if present
    hexSub = llDumpList2String(llParseString2List(hexSub,["-"],[]),"");
