// ================================================================
// THE CULTIVAR — HUD_Comms Patch Notes
// Version: 1.1
// ================================================================
//
// TheCultivar_HUD_Comms.lsl needs the following additions to
// support the Bagging Table and future world objects.
//
// ADD THESE TWO BLOCKS inside the listen() handler, under the
// section "Messages on our private channel (from world objects)"
// after the existing TC_REP_GIVEN block.
//
// ================================================================

// ----------------------------------------------------------------
// ADDITION 1: World object requesting filtered inventory
// Bagging table (and future objects) send this to get a
// filtered list of what the player is carrying.
//
// INSERT after the TC_REP_GIVEN block in the listen() handler:
// ----------------------------------------------------------------

/*

// World object requests a filtered inventory dump
// TC_INVENTORY_REQUEST|itemType|requestingObjectKey
else if (cmd == "TC_INVENTORY_REQUEST")
{
    string filterType = llList2String(parts, 1);
    key    reqObject  = (key)llList2String(parts, 2);

    // Ask inventory manager for the raw data
    // We pass the requesting object key so we can forward the response
    llMessageLinked(LINK_SET, CHAN_INVENTORY,
        "REQUEST_RAW_INVENTORY|" + filterType + "|" +
        (string)reqObject, NULL_KEY);
}

*/

// ----------------------------------------------------------------
// ADDITION 2: Handle RAW_INVENTORY response from inventory manager
// and forward it to the requesting world object.
//
// In the link_message() handler, add this block to handle
// messages on CHAN_COMMS:
// ----------------------------------------------------------------

/*

// Inventory manager responds with raw data — forward to world object
else if (cmd == "RAW_INVENTORY")
{
    // RAW_INVENTORY|serializedData|filterType|requestingObjectKey
    string rawData   = llList2String(parts, 1);
    // parts 2 = filterType (already used by inventory manager to filter)
    key    reqObject = (key)llList2String(parts, 3);

    if (reqObject != NULL_KEY)
    {
        llRegionSayTo(reqObject, 0,
            "TC_INVENTORY_DATA|" + rawData);
    }
}

*/

// ----------------------------------------------------------------
// ADDITION 3: Handle TC_ADD_ITEM from world objects
// Bagging table sends this after giving a bag to add it to
// the player's HUD inventory record.
//
// INSERT after TC_INVENTORY_REQUEST in the listen() handler:
// ----------------------------------------------------------------

/*

// World object telling HUD to add an item to inventory
// TC_ADD_ITEM|itemType|strainName|quality|qty|packager
else if (cmd == "TC_ADD_ITEM")
{
    llMessageLinked(LINK_SET, CHAN_INVENTORY,
        "ADD_ITEM|"         +
        llList2String(parts, 1) + "|" +   // itemType
        llList2String(parts, 2) + "|" +   // strainName
        llList2String(parts, 3) + "|" +   // quality
        llList2String(parts, 4) + "|" +   // qty
        llList2String(parts, 5),           // packager
        NULL_KEY);
}

*/

// ----------------------------------------------------------------
// ADDITION 4: Update REQUEST_RAW_INVENTORY in HUD_Inventory.lsl
//
// The existing handler in HUD_Inventory.lsl sends back:
//   "RAW_INVENTORY|" + serializeInventory()
//
// Update it to also pass through the filterType and reqObject
// so HUD_Comms can forward correctly:
//
// Change the REQUEST_RAW_INVENTORY handler to:
// ----------------------------------------------------------------

/*

else if (cmd == "REQUEST_RAW_INVENTORY")
{
    string filterType = llList2String(parts, 1); // may be empty
    string reqObjKey  = llList2String(parts, 2); // may be empty

    // Build filtered inventory if filterType specified
    string output;
    if (filterType != "" && filterType != "all")
    {
        // Only serialize items matching the filter type
        string filtered = "";
        integer len = llGetListLength(g_inventory);
        integer i;
        for (i = 0; i < len; i += STRIDE)
        {
            if (llList2String(g_inventory, i) == filterType)
            {
                string slot =
                    llList2String(g_inventory, i)   + "~" +
                    llList2String(g_inventory, i+1) + "~" +
                    llList2String(g_inventory, i+2) + "~" +
                    llList2String(g_inventory, i+3) + "~" +
                    llList2String(g_inventory, i+4);
                if (filtered == "") filtered = slot;
                else filtered += "^" + slot;
            }
        }
        output = filtered;
    }
    else
    {
        output = serializeInventory();
    }

    llMessageLinked(LINK_SET, CHAN_COMMS,
        "RAW_INVENTORY|" + output + "|" + filterType + "|" + reqObjKey,
        NULL_KEY);
}

*/

// ----------------------------------------------------------------
// ADDITION 5: TC_REMOVE_ITEM handler
//
// The bagging table sends TC_REMOVE_ITEM on the private channel.
// HUD_Comms needs to handle this and respond with TC_REMOVE_OK
// or TC_REMOVE_FAIL so the table knows whether to give the bag.
//
// INSERT after TC_ADD_ITEM in the listen() handler:
// ----------------------------------------------------------------

/*

// World object requesting item removal from HUD inventory
// TC_REMOVE_ITEM|itemType|strainName|quality|qty|packager
else if (cmd == "TC_REMOVE_ITEM")
{
    // Store the requesting object key so we can send the result back
    // We derive it from the listen event's 'id' parameter (the sender)
    // Pass through to inventory manager
    llMessageLinked(LINK_SET, CHAN_INVENTORY,
        "REMOVE_ITEM|"      +
        llList2String(parts, 1) + "|" +   // itemType
        llList2String(parts, 2) + "|" +   // strainName
        llList2String(parts, 3) + "|" +   // quality
        llList2String(parts, 4) + "|" +   // qty
        llList2String(parts, 5),           // packager
        id); // pass the sender key through as the id
}

// Then update REMOVE_SUCCESS / REMOVE_FAIL handlers to check
// if the removal was requested by a world object (id != NULL_KEY)
// and if so, notify the object directly:

// Change the REMOVE_SUCCESS block in link_message() to:
// else if (cmd == "REMOVE_SUCCESS")
// {
//     llMessageLinked(LINK_SET, CHAN_UI, "ITEM_USED|" + msg, NULL_KEY);
//     // If id is set, a world object is waiting for confirmation
//     if (id != NULL_KEY)
//         llRegionSayTo(id, 0, "TC_REMOVE_OK");
// }
// else if (cmd == "REMOVE_FAIL")
// {
//     llMessageLinked(LINK_SET, CHAN_UI, "ITEM_FAILED|" + msg, NULL_KEY);
//     if (id != NULL_KEY)
//         llRegionSayTo(id, 0, "TC_REMOVE_FAIL");
// }

*/

// ----------------------------------------------------------------
// ALSO ADD: TC_OBJECT_PING listener to HUD_Comms
//
// When any world object (bagging table, jar, etc.) touches and
// pings, the HUD needs to hear it and respond with TC_REGISTER.
//
// ADD to state_entry() and on_rez():
// ----------------------------------------------------------------

/*

integer TC_OBJECT_PING_CHAN = -111222333;

// In startListening():
llListen(TC_OBJECT_PING_CHAN, "", NULL_KEY, "");

// In listen(), add handling for TC_PING:
// (This goes BEFORE the channel == g_privateChannel check)

if (channel == TC_OBJECT_PING_CHAN && cmd == "TC_PING")
{
    // TC_PING|objectKey|objectType
    key    objectKey  = (key)llList2String(parts, 1);
    // Respond with our registration info
    llRegionSayTo(objectKey, 0,
        "TC_REGISTER|" + (string)g_ownerKey + "|" +
        (string)g_privateChannel + "|" + g_ownerName);
}

*/

// ================================================================
// SUMMARY OF CHANGES TO MAKE IN EXISTING FILES:
//
// TheCultivar_HUD_Comms.lsl:
//   1. Add TC_OBJECT_PING_CHAN integer constant
//   2. Add llListen(TC_OBJECT_PING_CHAN...) in startListening()
//   3. Add TC_PING handler in listen()
//   4. Add TC_INVENTORY_REQUEST handler in listen()
//   5. Add TC_ADD_ITEM handler in listen()
//   6. Add TC_REMOVE_ITEM handler in listen()
//   7. Update REMOVE_SUCCESS / REMOVE_FAIL to notify world objects
//   8. Add RAW_INVENTORY handler in link_message()
//
// TheCultivar_HUD_Inventory.lsl:
//   1. Update REQUEST_RAW_INVENTORY to accept and pass through
//      filterType and reqObjKey parameters
// ================================================================

