    changed(integer change)
    {
        if (change & CHANGED_OWNER)
        {
            llLinksetDataDeleteFound("stash_", "");
            llResetScript();
        }
        if (change & CHANGED_INVENTORY)
        {
            rebuildContents();
            updateDisplay();
            updateHoverText();
        }
    }

