                  llList2Vector(TIER_COLORS, g_tier), 1.0);
    else
        llSetText("THE CULTIVAR\nGrow Light [OFF]",
                  <0.5, 0.5, 0.5>, 0.7);
}

// ----------------------------------------------------------------
// Broadcast bonus to all nearby plants
// ----------------------------------------------------------------
broadcastBonus()
{
